styl:
.white-bg.b-new-text-16 {  background:#fff  }
.b-new-text-16 .label, .b-new-text-16 .plys-logo {  display:inline-block  }
.b-new-text-16 .plys-logo {  padding:5px 12px;border:.8px solid #d2d2d2;border-radius:9.6px;vertical-align:middle  }
@media screen and (max-width:600px) {
  .b-new-text-16 .plys-logo {  margin-bottom:10px!important  }
}
.b-new-text-16 .little-big-text {  font-family:Helvetica!important;font-weight:700;font-size:18px;line-height:25px;color:#413e43  }
.b-new-text-16 .image-block {  display:inline-block;width:100%  }
@media screen and (max-width:600px) {
  .b-new-text-16 .image-block {  text-align:center!important  }
}
.b-new-text-16 .min-image {  width:180px!important;float:right  }
@media screen and (max-width:600px) {
  .b-new-text-16 .min-image {  float:none!important;padding-left:15px!important;margin-bottom:10px!important  }
}
.b-new-text-16 .disp-ib {  display:inline-block;vertical-align:middle  }
.b-new-text-16 .wb-bw {  word-break:break-word  }
.b-new-text-16 .pb12 {  padding-bottom:12px  }
.b-new-text-16 .pb44 {  padding-bottom:44px  }
.b-new-text-16 .pt44, .b-new-text-16 .pt45 {  padding-top:44px  }
@media screen and (max-width:600px) {
  .b-new-text-16 .padding {  padding:0 50px  }
}
.b-new-text-16 .social-links {  display:block;text-align:center  }
.br-full-16.b-new-text-16 {  border-radius:16px;-moz-border-radius:16px;-webkit-border-radius:16px  }
.bg-bord-full.b-new-text-16 {  border:1px solid #eae9e9  }
.b-new-text-16 .pb32 {  padding-bottom:32px  }
.b-new-text-16 .countries-block-new {  width:148px;display:inline-block;float:none;background:#f6f6f6;border-radius:24px;vertical-align:top  }
@media screen and (max-width:600px) {
  .b-new-text-16 .countries-block-new {  display:block!important;width:230px!important;margin:10px auto 0!important  }
  .b-new-text-16 .countries-block-new.fisrt-block {  margin:0 auto!important  }
}
.b-new-text-16 .mar-mob {  margin:0 10px  }
.b-new-text-16 .padding {  padding:24px  }
.b-new-text-16 .asset-image {  float:none;width:40px!important;padding-bottom:32px  }
.b-new-text-16 .fw-min {  font-size:15px!important  }
